SELECT price_id
FROM tb_item_partner_price
WHERE tenant_id = #{tenantId}
    AND material_id = #{materialId}
    AND customer_id = CAST(#{customerId} AS BIGINT)
    AND trade_type = #{tradeType}
    AND use_at = 'Y'
    AND end_dt = CAST(#{startDt} AS DATE) - 1
    AND price_id != #{priceId}
LIMIT 1

DELETE FROM tb_item_default_supplier d WHERE d.tenant_id = #{tenantId} AND d.material_id IN
#{materialId}
AND NOT EXISTS ( SELECT 1 FROM tb_item_partner_price p WHERE p.tenant_id = d.tenant_id AND p.material_id = d.material_id AND p.customer_id = d.customer_id AND p.trade_type = '매입' AND p.use_at = 'Y') RETURNING d.material_id

SELECT DISTINCT p.trade_type
FROM tb_item_partner_price p
WHERE p.tenant_id = #{tenantId}
  AND p.price_id IN

    #{priceId}

SELECT DISTINCT p.material_id
FROM tb_item_partner_price p
WHERE p.tenant_id = #{tenantId}

  AND p.trade_type = #{tradeType}

  AND p.price_id IN

    #{priceId}

SELECT s.material_id AS "materialId", s.customer_id AS "supplierId", c.customer_code AS "supplierCode", c.customer_name AS "supplierName", pr.unit_price AS "unitPrice", pr.tax_type AS "taxType", pr.vat_included_at AS "vatIncludedAt", pr.foreign_unit_price AS "foreignUnitPrice", pr.currency AS "foreignCurrency", pr.order_type AS "orderType", oci.item_nm AS "orderTypeName" FROM ( SELECT cnt.material_id, CASE WHEN cnt.customer_count = 1 THEN cnt.only_customer_id ELSE d.customer_id END AS customer_id, cnt.tenant_id FROM ( SELECT p.tenant_id, p.material_id, COUNT(DISTINCT p.customer_id) AS customer_count, MIN(p.customer_id) AS only_customer_id FROM tb_item_partner_price p JOIN tb_customer_info pcu ON pcu.customer_id = p.customer_id AND pcu.tenant_id = p.tenant_id AND pcu.use_at = 'Y' WHERE p.tenant_id = #{tenantId} AND p.trade_type = '매입' AND p.use_at = 'Y' AND p.material_id IN
#{materialId}
GROUP BY p.tenant_id, p.material_id ) cnt LEFT JOIN tb_item_default_supplier d ON d.tenant_id = cnt.tenant_id AND d.material_id = cnt.material_id ) s JOIN tb_customer_info c ON c.customer_id = s.customer_id AND c.tenant_id = s.tenant_id AND c.use_at = 'Y' LEFT JOIN LATERAL ( SELECT p.unit_price, p.tax_type, p.vat_included_at, p.foreign_unit_price, p.currency, p.order_type FROM tb_item_partner_price p WHERE p.tenant_id = s.tenant_id AND p.material_id = s.material_id AND p.customer_id = s.customer_id AND p.trade_type = '매입' AND p.use_at = 'Y' AND p.start_dt <= CAST(#{baseDt} AS DATE) AND (p.end_dt IS NULL OR p.end_dt >= CAST(#{baseDt} AS DATE)) ORDER BY p.start_dt DESC, p.price_id DESC LIMIT 1 ) pr ON TRUE LEFT JOIN tb_common_code_group ocg ON ocg.tenant_id = s.tenant_id AND ocg.group_code = 'PURCHASE_ORDER_TYPE' LEFT JOIN tb_common_code_item oci ON oci.group_id = ocg.common_code_group_id AND oci.item_code = pr.order_type

SELECT m.material_id AS "materialId", m.material_code AS "materialCode", m.material_name AS "materialName" FROM tb_material_info m JOIN ( SELECT p.material_id, COUNT(DISTINCT p.customer_id) AS customer_count FROM tb_item_partner_price p JOIN tb_customer_info pcu ON pcu.customer_id = p.customer_id AND pcu.tenant_id = p.tenant_id AND pcu.use_at = 'Y' WHERE p.tenant_id = #{tenantId} AND p.trade_type = '매입' AND p.use_at = 'Y' AND p.material_id IN
#{materialId}
GROUP BY p.material_id ) pc ON pc.material_id = m.material_id AND pc.customer_count >= 2 WHERE m.tenant_id = #{tenantId} AND NOT EXISTS ( SELECT 1 FROM tb_item_default_supplier d WHERE d.tenant_id = m.tenant_id AND d.material_id = m.material_id) ORDER BY m.material_code
